<?php
require_once __DIR__.'/common.php';cron_start('scan_drive',900);$folders=$db->all("SELECT f.*,c.channel_name,c.status channel_status FROM drive_folders f JOIN youtube_channels c ON c.id=f.youtube_channel_id WHERE f.enabled=1 AND c.status='connected' ORDER BY f.id");
foreach($folders as $folder){try{$token=$services->tokenForDrive((int)$folder['drive_connection_id']);$drive=new GoogleDrive($token);$folderInfo=$drive->folder($folder['folder_id']);if(($folderInfo['mimeType']??'')!=='application/vnd.google-apps.folder')throw new RuntimeException('Configured Drive ID is not a folder.');$files=$drive->listVideos($folder['folder_id']);$channel=$db->one('SELECT * FROM youtube_channels WHERE id=?',[$folder['youtube_channel_id']]);foreach($files as $file){try{$videoId=$db->insert("INSERT INTO videos(youtube_channel_id,drive_folder_id,drive_file_id,drive_file_name,mime_type,file_size,title,description,tags_json,hashtags_json,category_id,privacy_status,made_for_kids,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'Pending',?,?)",[$folder['youtube_channel_id'],$folder['id'],$file['id'],$file['name'],$file['mimeType']??null,(int)($file['size']??0),clean_title_from_filename($file['name']),$channel['default_description']??'',json_encode_safe(json_decode($channel['default_tags_json']??'[]',true)?:[]),json_encode_safe(json_decode($channel['default_hashtags_json']??'[]',true)?:[]),$channel['default_category_id']??'22',$channel['default_privacy_status']??'private',(int)($channel['default_made_for_kids']??0),now_sql(),now_sql()]);$services->log('INFO','drive.discovery','New Drive video discovered',['video_id'=>$videoId,'drive_file_id'=>$file['id'],'channel_id'=>$folder['youtube_channel_id']]);}catch(PDOException $e){if((int)$e->errorInfo[1]!==1062)throw $e;}}$db->exec('UPDATE drive_folders SET last_scanned_at=?,updated_at=? WHERE id=?',[now_sql(),now_sql(),$folder['id']]);}catch(Throwable $e){$services->log('ERROR','drive.scan_failed',$e->getMessage(),['folder_id'=>$folder['id'],'channel_id'=>$folder['youtube_channel_id']]);$db->exec("UPDATE google_drive_connections SET status='error',last_error=?,updated_at=? WHERE id=?",[$e->getMessage(),now_sql(),$folder['drive_connection_id']]);}}
